# Long-form guide sections appended to existing pages (SEO depth + contextual interlinking).
# Executed by build.py after the helpers are defined; uses L(), guide() and section().

P = {
    'home': '', 'platform': 'platform/', 'realtime': 'real-time/', 'ai': 'ai-forecasting/', 'plans': 'plans/',
    'solutions': 'solutions/', 'privacy': 'privacy-by-design/', 'contact': 'contact/', 'faq': 'faq/', 'places': 'places/',
    'councils': 'solutions/councils/', 'universities': 'solutions/universities/', 'government': 'solutions/government/',
    'buildings': 'solutions/buildings/', 'retail': 'solutions/retail/', 'parks': 'solutions/parks-and-streets/',
    'campuses': 'places/campuses/', 'libraries': 'places/libraries/', 'shopping': 'places/shopping-centres/',
    'venues': 'places/stadiums-and-venues/', 'streets': 'places/streets-and-laneways/', 'foreshores': 'places/parks-and-foreshores/',
    'offices': 'places/office-towers/', 'govbuildings': 'places/government-buildings/',
}


def L(key, text):
    return '<a href="{R}%s">%s</a>' % (P[key], text)


def R(key, title, text):
    return (P[key], title, text)


GUIDES = {}

GUIDES['platform'] = guide('Guide', 'What is a people counting and place analytics platform?', [
    (None, 'A people counting platform turns raw sensor counts into answers about how a place is used. Place Performance goes further than a dashboard. It covers the whole chain, from choosing and installing sensors to reporting, ' + L('ai', 'forecasting') + ' and AI recommendations, so the numbers you rely on are trustworthy from the first day.'),
    ('From sensor to decision', 'Every deployment starts with a site survey. Our team looks at entrances, ceiling heights, lighting, movement patterns, power and connectivity, then designs a sensor plan. Indoors that usually means 3D people counters at entrances and over key zones. Outdoors it can include specialist sensors for ' + L('parks', 'pedestrians, cyclists and vehicles') + '. Counting happens on the device, so only anonymous numbers are sent to the platform, as explained in ' + L('privacy', 'privacy by design') + '.'),
    ('Organised the way you manage places', 'Data is structured as portfolio, site, space and zone. A council can see every library at once, then drill into one branch, one floor and a single children\'s area. Visits, live occupancy, dwell time and peak periods roll up automatically, so a regional manager and a branch manager look at the same numbers at different levels of detail. ' + L('realtime', 'Live floorplans') + ' show each zone filling and emptying as it happens.'),
    ('Insight, not just information', 'Dashboards tell you what happened. The platform also tells you what to do about it: threshold ' + L('realtime', 'alerts') + ' before a room overflows, scheduled reports for managers and boards, visitation forecasts, scenario planning and a Place Assistant that answers questions in plain English. Capabilities are packaged into ' + L('plans', 'four plan levels') + ', so you can start with counting and add intelligence when your organisation is ready.'),
    ('Built for Australian public and shared places', 'The same platform serves ' + L('councils', 'councils') + ', ' + L('universities', 'universities') + ', ' + L('government', 'government agencies') + ', ' + L('buildings', 'commercial buildings') + ', ' + L('retail', 'shopping centres') + ' and ' + L('parks', 'outdoor public spaces') + '. Each sector uses the same trusted data for different decisions, from crowd safety in a ' + L('libraries', 'library') + ' to consolidating floors in an ' + L('offices', 'office tower') + '.'),
], [R('realtime', 'Real-time monitoring', 'Live occupancy, floorplans and alerts'), R('ai', 'AI &amp; forecasting', 'Forecasts, scenarios and the Place Assistant'),
    R('privacy', 'Privacy by design', 'How counting stays anonymous'), R('places', 'Places we measure', 'Libraries, campuses, venues and more'), R('plans', 'Plans', 'Essentials to Executive')])

GUIDES['real-time'] = guide('Guide', 'Why real-time occupancy matters.', [
    (None, 'Occupancy is the number of people in a space right now, compared with how many it can safely or comfortably hold. Historical counts tell you about last month. Real-time occupancy lets you act in the moment: open an overflow room, redeploy staff, slow entry at a gate or tell people where there is space.'),
    ('Live floorplans, room by room', 'Upload a floorplan for each level, draw rooms and zones as shapes, and every zone shows its live headcount, coloured green, amber, orange or red as it fills. Managers see at a glance which areas need attention, and the same view works on a phone for staff walking the floor. It is especially useful in ' + L('libraries', 'libraries') + ', ' + L('campuses', 'campus study spaces') + ' and ' + L('offices', 'office floors') + '.'),
    ('Alerts that reach the right person', 'Threshold rules watch occupancy, queue wait times, entry and exit imbalances, sensor health and unusual activity. When a rule is breached the right people are notified by email, SMS, Microsoft Teams or in-app, with escalation if nobody acknowledges it. ' + L('councils', 'Councils') + ' use this for events and community facilities, and ' + L('venues', 'stadiums and venues') + ' use it to manage crowd capacity at entries.'),
    ('From portfolio to a single zone', 'Each site on the portfolio map is coloured by its busiest zone, so one overcrowded room flags the whole site even when the building overall looks quiet. One click takes you from the map to the site, the floor and the room. Read more about how data is organised on the ' + L('platform', 'platform page') + '.'),
    ('Real time and history together', 'Every live count is stored, so the same data feeds trends, peak-period analysis, reports and ' + L('ai', 'visitation forecasting') + '. Operational teams use the live view during the day, and planners use the history to set opening hours, rosters and cleaning schedules. In ' + L('shopping', 'shopping centres') + ', for example, live food court occupancy triggers cleaning while weekly peaks inform rosters.'),
], [R('libraries', 'Libraries', 'Live zone occupancy and study space'), R('venues', 'Stadiums &amp; venues', 'Crowd capacity alerts'),
    R('councils', 'Councils &amp; civic', 'Safety and service'), R('ai', 'AI &amp; forecasting', 'Predict tomorrow\'s peaks'), R('platform', 'Platform', 'How it all fits together')])

GUIDES['ai-forecasting'] = guide('Guide', 'How AI and forecasting improve planning for places.', [
    (None, 'Most organisations already know roughly when their places are busy. Forecasting makes that knowledge precise and forward-looking, and AI turns it into specific, ranked recommendations. Together they move decisions from instinct to evidence.'),
    ('Forecasting visitation and occupancy', 'Forecasts are built from each place\'s own history, including time of day, day of week and seasonal patterns such as school holidays and semester breaks. Each forecast comes with a confidence range that widens further into the future, so planners can see both the most likely outcome and the realistic range. A ' + L('libraries', 'library') + ' can see that Saturday story time will push the children\'s area over capacity, and a ' + L('campuses', 'campus') + ' can anticipate exam-period demand for study space.'),
    ('Scenario planning before you commit', 'Scenario planning lets you change assumptions such as opening hours, capacity, staffing or layout and immediately see the projected effect on visits, peak occupancy, queues and cost per visit. ' + L('councils', 'Councils') + ' use it to test extended trading hours, and ' + L('retail', 'retail precincts') + ' use it to model the effect of a new entrance or tenant mix.'),
    ('AI insights every morning', 'Each morning the platform reviews trends, peaks, capacity breaches and comparisons across your sites, then writes plain-language recommendations ranked by impact. Every insight shows the evidence behind it and a confidence score, so it can be checked rather than taken on trust.'),
    ('The Place Assistant', 'The Place Assistant answers questions in plain English using your live data: which rooms are over capacity, when a site is busiest, which sensors are offline, or how this week compares with last. Answers link straight to the places they mention, and it only sees the data your role is allowed to see. Read how data is protected in ' + L('privacy', 'privacy by design') + '.'),
    ('From operations to capital decisions', 'The same intelligence supports rosters and cleaning today and capital works tomorrow. ' + L('government', 'Government agencies') + ' use utilisation trends to consolidate property, ' + L('universities', 'universities') + ' test whether new buildings are really needed, and ' + L('buildings', 'property owners') + ' measure whether a refit paid off. These capabilities are part of the Executive level on the ' + L('plans', 'plans page') + '.'),
], [R('plans', 'Plans', 'AI is included in Executive'), R('government', 'Government', 'Portfolio rationalisation'), R('universities', 'Universities', 'Capital planning on evidence'),
    R('realtime', 'Real-time monitoring', 'The live data behind every forecast'), R('privacy', 'Privacy by design', 'What the AI can and cannot see')])

GUIDES['plans'] = guide('Guide', 'Choosing the right plan level.', [
    (None, 'Place Performance plans follow a maturity path. Each level includes everything in the levels below it, so moving up never means replacing hardware or losing history. Most organisations choose a level based on the decisions they need to make today, then grow.'),
    ('Essentials: know what is happening', 'Essentials covers visitor counting, entries and exits, live occupancy against capacity, peak periods, dwell time, dashboards, automated reports and device health. It suits a single ' + L('libraries', 'library') + ', community centre or ' + L('shopping', 'shopping centre') + ' that needs reliable visitation numbers for reporting and day-to-day operations.'),
    ('Insights: know why it is happening', 'Insights adds live floorplans, heat maps, visitor flow, zone comparison, repeat visitation and historical trends. It is the right level when you need to understand how people use space inside a building, for example ' + L('campuses', 'study spaces on a campus') + ' or amenities on ' + L('offices', 'office floors') + '. See these features on the ' + L('realtime', 'real-time page') + '.'),
    ('Professional: improve how places perform', 'Professional adds multi-site portfolio views, alert rules with escalation, queue and operations analytics, integrations with point-of-sale, Wi-Fi and building management systems, the Place Performance Score and single sign-on. It suits ' + L('councils', 'councils') + ' and ' + L('buildings', 'property owners') + ' running several sites.'),
    ('Executive: lead with intelligence', 'Executive adds the performance index and benchmarking, AI insights, the Place Assistant, forecasting, scenario modelling, investment analysis and board reporting packs. It is designed for leadership teams making portfolio and capital decisions, such as ' + L('government', 'government property rationalisation') + '. Learn more on the ' + L('ai', 'AI and forecasting page') + '.'),
    ('What every plan includes', 'Every plan includes the sensors, site survey, installation, commissioning, the analytics platform, device health monitoring and ongoing support from our Australian team. Pricing depends on the number of sites and devices. The quickest way to find the right level is a pilot at one site, which you can arrange through the ' + L('contact', 'contact page') + '.'),
], [R('contact', 'Book a demo', 'Scope a pilot for your site'), R('platform', 'Platform', 'What is included end to end'), R('ai', 'AI &amp; forecasting', 'Executive capabilities'),
    R('realtime', 'Real time', 'Floorplans, alerts and live data'), R('faq', 'FAQ', 'Common questions about plans')])

GUIDES['solutions'] = guide('Guide', 'One measurement platform, many kinds of place.', [
    (None, 'Councils, universities, agencies, property owners and precinct managers ask different questions, but they all need the same thing first: accurate, anonymous numbers about how their places are used. Place Performance provides that foundation, then shapes dashboards, alerts and reports around each sector\'s decisions.'),
    ('Choose by sector', L('councils', 'Councils') + ' focus on crowd safety, service levels and evidence for funding. ' + L('universities', 'Universities') + ' measure space utilisation against bookings. ' + L('government', 'Government agencies') + ' right-size office portfolios after the shift to hybrid work. ' + L('buildings', 'Commercial property owners') + ' clean and condition space on demand. ' + L('retail', 'Shopping centres and precincts') + ' connect footfall to sales, and ' + L('parks', 'public-realm managers') + ' count pedestrians, cyclists and vehicles outdoors.'),
    ('Choose by place', 'You can also start from the type of place you manage: ' + L('libraries', 'libraries') + ', ' + L('campuses', 'university campuses') + ', ' + L('shopping', 'shopping centres') + ', ' + L('venues', 'stadiums and venues') + ', ' + L('streets', 'streets and laneways') + ', ' + L('foreshores', 'parks and foreshores') + ', ' + L('offices', 'office towers') + ' and ' + L('govbuildings', 'government buildings') + '. Each page explains what is measured there and how sensors are installed.'),
    ('Shared foundations', 'Whatever the sector, every deployment uses the same ' + L('platform', 'platform') + ': privacy-safe sensors, ' + L('realtime', 'real-time occupancy and alerts') + ', automated reporting and, at higher levels, ' + L('ai', 'forecasting and AI insights') + '. Many organisations use one deployment for several purposes at once, such as a council measuring both library occupancy and shared-path cycling.'),
], [R('places', 'Places we measure', 'Browse by type of place'), R('platform', 'Platform', 'How it works'), R('plans', 'Plans', 'Pick a capability level'), R('contact', 'Book a demo', 'Talk to our team')])

GUIDES['privacy-by-design'] = guide('Guide', 'How anonymous people counting works.', [
    (None, 'Privacy-safe people counting answers questions about places, such as how many people are in a room or when an entrance is busiest, without collecting information about who those people are. Place Performance is designed so that personal information never needs to leave the device.'),
    ('What the sensor sees', 'Our 3D people counters use depth sensing to detect people as shapes moving through the field of view, typically from a ceiling-mounted position looking down. Processing happens on the device itself, which converts what it detects into counts: people in, people out, and how many are present in each zone.'),
    ('What leaves the site', 'Only anonymous numbers are transmitted to the platform: counts, occupancy, dwell time and movement between zones. Video is not streamed to or stored by the platform, faces are not recognised, and no names or identities are collected. Optional anonymous demographic estimates are only used where the hardware supports them and you choose to enable them.'),
    ('Who can see the data', 'Inside the platform, role-based access controls decide which sites and features each user can see. Single sign-on can be enforced, and administrative actions are recorded in an audit log. The ' + L('ai', 'Place Assistant') + ' only receives the data the asking user is permitted to see.'),
    ('Supporting your obligations', 'Anonymous, edge-processed counting with minimal collection is designed to support obligations under Australian privacy law, which matters for ' + L('councils', 'councils') + ', ' + L('government', 'government agencies') + ' and ' + L('universities', 'universities') + ' measuring public spaces such as ' + L('libraries', 'libraries') + ' and ' + L('foreshores', 'parks') + '. We can provide documentation to support your privacy impact assessment. Read more about the hardware on the ' + L('platform', 'platform page') + '.'),
], [R('platform', 'Platform', 'Sensors and edge processing'), R('councils', 'Councils &amp; civic', 'Counting in public facilities'), R('government', 'Government', 'Anonymous attendance data'),
    R('faq', 'FAQ', 'More privacy questions'), R('contact', 'Contact', 'Request privacy documentation')])

GUIDES['contact'] = guide('Guide', 'What to expect from a demo and pilot.', [
    (None, 'A demo is a 30-minute walkthrough of the platform using data shaped like your own places. We focus on the questions you want to answer, whether that is crowd capacity in a ' + L('libraries', 'library') + ', utilisation on a ' + L('campuses', 'campus') + ' or occupancy across a ' + L('government', 'government portfolio') + '.'),
    ('The site survey', 'If a pilot makes sense, our team surveys your locations: entrances, ceiling heights, layouts, power, connectivity and privacy requirements. From that we prepare a sensor plan and recommend a ' + L('plans', 'plan level') + '.'),
    ('Your pilot', 'A pilot at one site is typically live within weeks. You get the same ' + L('realtime', 'real-time dashboards') + ', floorplans and reports as a full deployment, using your own data, so you can judge accuracy and value before rolling out further. Want to look around first? Try the live demo or read the ' + L('faq', 'frequently asked questions') + '.'),
], [R('plans', 'Plans', 'Compare capability levels'), R('platform', 'Platform', 'How the service works'), R('privacy', 'Privacy by design', 'How counting stays anonymous'), R('faq', 'FAQ', 'Answers to common questions')])

# ---------------- Sector guides ----------------
GUIDES['solutions/councils'] = guide('Guide', 'People counting for local government.', [
    (None, 'Councils run some of the most varied places in Australia: libraries, community and aquatic centres, customer service points, town halls, events, parks and shared paths. People counting gives each of them a consistent, independent measure of how the community actually uses them.'),
    ('Libraries and community centres', 'In ' + L('libraries', 'libraries') + ', sensors at the entrance count visits while zone sensors measure occupancy in reading rooms, children\'s areas and study spaces. ' + L('realtime', 'Live floorplans') + ' show where crowding builds, and alerts tell staff before a space reaches its limit. Over time, peak-period data shows whether opening hours and rosters match community demand.'),
    ('Events and outdoor spaces', 'Temporary counting can be deployed for festivals, markets and civic events to track attendance and crowd numbers at entries. Permanent outdoor sensors measure ' + L('foreshores', 'parks and foreshores') + ' and ' + L('streets', 'streets and town centres') + ', including pedestrian and cyclist counts on shared paths, so active-transport investment can be measured. See ' + L('parks', 'parks, trails and streets') + ' for more.'),
    ('Evidence for funding and planning', 'Automated reports provide visitation numbers for annual reports, grant applications and council briefings without manual tallies. With ' + L('ai', 'forecasting and scenario planning') + ', councils can test the effect of extended hours or new facilities before committing budget.'),
    ('Privacy and trust', 'Counting is anonymous, with processing on the device and no images or personal information collected, which supports community trust and privacy obligations. Read more in ' + L('privacy', 'privacy by design') + '.'),
], [R('libraries', 'Libraries', 'Zone occupancy and study space'), R('foreshores', 'Parks &amp; foreshores', 'Visitation outdoors'), R('venues', 'Stadiums &amp; venues', 'Event crowd capacity'),
    R('streets', 'Streets &amp; laneways', 'Pedestrian counts'), R('realtime', 'Real time', 'Alerts and live floorplans')])

GUIDES['solutions/universities'] = guide('Guide', 'Measuring space utilisation on campus.', [
    (None, 'Universities manage large, expensive estates, yet booking systems only show what was reserved, not what was used. Measured occupancy closes that gap, showing how lecture theatres, tutorial rooms, labs, libraries and informal study spaces are really used across the week and the semester.'),
    ('Utilisation you can act on', 'Utilisation combines frequency (how often a room is used) with occupancy (how full it is when used). Sensors provide both, room by room and hour by hour, so timetabling teams can move classes into right-sized rooms and free up space that is booked but empty. Read more about ' + L('campuses', 'measuring campuses') + '.'),
    ('A better student experience', 'Live occupancy on ' + L('realtime', 'floorplans') + ' can show students where free study space is right now, reducing time spent searching and spreading demand more evenly across buildings. University ' + L('libraries', 'libraries') + ' use the same data to staff help desks and plan opening hours around exam periods.'),
    ('Capital planning on evidence', 'Before committing to a new building, utilisation trends and ' + L('ai', 'demand forecasts') + ' show whether more space is really needed or existing space could be used better. After a refurbishment, before-and-after analysis shows whether it worked. These capabilities sit in the Executive level on the ' + L('plans', 'plans page') + '.'),
    ('Anonymous by design', 'No individual students are identified. Counting runs on the device and only anonymous numbers leave each building, as described in ' + L('privacy', 'privacy by design') + '.'),
], [R('campuses', 'Campuses', 'Room and space utilisation'), R('libraries', 'Libraries', 'Study space and help desks'), R('ai', 'AI &amp; forecasting', 'Demand forecasts'),
    R('plans', 'Plans', 'Insights and Executive levels'), R('privacy', 'Privacy by design', 'No individuals identified')])

GUIDES['solutions/government'] = guide('Guide', 'Office occupancy data for the public sector.', [
    (None, 'Hybrid work has changed how government offices are used. Attendance now varies by day, team and floor, and headcount or desk bookings no longer predict how much space is needed. Measured occupancy gives agencies an accurate, anonymous picture of real use.'),
    ('Right-sizing the portfolio', 'Occupancy across every floor and building, compared over months, shows average and peak utilisation and identifies floors that are consistently under-used. Portfolio views rank sites so consolidation decisions rest on evidence. See how this works for ' + L('govbuildings', 'government buildings') + ' and ' + L('offices', 'office towers') + '.'),
    ('Public-facing services', 'Service centres and shopfronts use queue and wait-time monitoring against service targets, with ' + L('realtime', 'alerts') + ' when targets are at risk. Live occupancy supports capacity limits and emergency management at sites that welcome the public.'),
    ('Transparent reporting', 'Scheduled reports and board packs summarise attendance, utilisation and trends for executives, ministers and audit, without manual data gathering. ' + L('ai', 'Forecasting and scenario planning') + ' help test the effect of consolidation before it happens.'),
    ('Security and privacy', 'Counting is anonymous and processed on the device, access is role-based with single sign-on, and hosting arrangements can be discussed to meet agency requirements. Read more in ' + L('privacy', 'privacy by design') + '.'),
], [R('govbuildings', 'Government buildings', 'Floors, shopfronts and service centres'), R('offices', 'Office towers', 'Floor and amenity utilisation'), R('ai', 'AI &amp; forecasting', 'Scenario planning'),
    R('privacy', 'Privacy by design', 'Anonymous counting'), R('plans', 'Plans', 'Professional and Executive')])

GUIDES['solutions/buildings'] = guide('Guide', 'Occupancy analytics for commercial property.', [
    (None, 'For building owners and managers, occupancy is the link between how a building is used and what it costs to run. Measuring it accurately lets you clean, condition and staff space on demand, give tenants evidence about their workplace, and prove the value of capital works.'),
    ('Operate on demand', 'Demand-based cleaning triggers a clean after a set number of visits rather than on a fixed timetable. Occupancy shared with the building management system lets HVAC and lighting respond to real use, so empty floors are not conditioned. Live ' + L('realtime', 'floorplans and alerts') + ' keep facilities teams informed through the day.'),
    ('Tenant and amenity insight', 'Floor and tenancy occupancy, meeting room use and visitor flow between lifts, entrances and amenities show how space performs. Tenants can be given access to their own data, which supports workplace strategy and lease discussions. Read more about ' + L('offices', 'office towers') + '.'),
    ('Prove the return on refits', 'Before-and-after analysis compares occupancy, utilisation and dwell around a refurbishment, and ' + L('ai', 'forecasting') + ' supports the business case for the next one. The Place Performance Score gives each building one headline performance number.'),
    ('Reliable data, locally supported', 'Every sensor appears on your floorplans with live status, and our Australian support team is alerted if one goes quiet. See how the service fits together on the ' + L('platform', 'platform page') + ', or compare levels on the ' + L('plans', 'plans page') + '.'),
], [R('offices', 'Office towers', 'Floor and amenity utilisation'), R('govbuildings', 'Government buildings', 'Portfolio occupancy'), R('realtime', 'Real time', 'Floorplans and alerts'),
    R('ai', 'AI &amp; forecasting', 'Refit and investment analysis'), R('platform', 'Platform', 'Sensors and support')])

GUIDES['solutions/retail'] = guide('Guide', 'Footfall analytics for shopping centres and precincts.', [
    (None, 'Footfall is the most basic measure of a retail destination\'s health. Combined with sales, dwell and zone data it becomes a powerful tool for leasing, marketing, operations and asset strategy.'),
    ('Visitation by entrance, zone and hour', 'Entrance counters measure footfall by door, hour and day, while zone sensors show how visitors spread across malls, wings and food courts. Peak-period grids reveal the busiest hours so rosters, cleaning and security match demand. Read more about ' + L('shopping', 'shopping centres') + '.'),
    ('Conversion and tenant performance', 'Point-of-sale integrations combine footfall with sales to calculate conversion and sales per visitor by zone. Ranking zones and tenants highlights strong and weak areas and supports leasing and rent reviews.'),
    ('Events and campaigns', 'Comparing footfall, dwell and conversion during a promotion with the expected baseline shows the uplift it created. ' + L('ai', 'Scenario planning') + ' helps test changes such as new entrances or trading hours before committing.'),
    ('Precincts and streets', 'Outdoor counting extends the picture to ' + L('streets', 'streets and laneways') + ' around a centre, useful for precinct managers and ' + L('councils', 'councils') + ' measuring town centre activity. ' + L('realtime', 'Real-time alerts') + ' help manage queues at service desks and food courts.'),
], [R('shopping', 'Shopping centres', 'Footfall and dwell time'), R('streets', 'Streets &amp; laneways', 'Precinct pedestrian counts'), R('venues', 'Stadiums &amp; venues', 'Event crowds'),
    R('ai', 'AI &amp; forecasting', 'Campaign and scenario analysis'), R('realtime', 'Real time', 'Queues and live occupancy')])

GUIDES['solutions/parks-and-streets'] = guide('Guide', 'Counting people, cyclists and vehicles outdoors.', [
    (None, 'Outdoor places are harder to measure than buildings: there are no doors, conditions vary and power or connectivity may be limited. Yet councils and public-realm managers still need evidence of how parks, trails, foreshores, plazas and streets are used, and how that changes over time.'),
    ('Paths, trails and active transport', 'Counting on shared paths and trails measures pedestrian and cyclist volumes and direction, so the effect of new infrastructure can be tracked. Trends by day, week and season show growth and help prioritise maintenance. Read more about ' + L('foreshores', 'parks and foreshores') + '.'),
    ('Streets, plazas and town centres', 'Pedestrian counts at key points in ' + L('streets', 'streets and laneways') + ' show how activity varies by hour, day and season, supporting place management, events and economic development. Vehicle counting can be added at roads, access points and car parks.'),
    ('Before, during and after projects', 'Measuring before a project begins, during works and after completion shows how a new crossing, path or plaza has changed the way people use an area. ' + L('ai', 'Forecasting') + ' extends this into planning for future demand.'),
    ('Designed for Australian conditions', 'Each location is assessed for power and connectivity, and the technology is chosen to suit urban, coastal or remote environments. Deployments can be permanent or temporary for events. See how it fits together on the ' + L('platform', 'platform page') + ' and for ' + L('councils', 'councils') + '.'),
], [R('foreshores', 'Parks &amp; foreshores', 'Visitation trends'), R('streets', 'Streets &amp; laneways', 'Pedestrian counts'), R('councils', 'Councils &amp; civic', 'Council use cases'),
    R('venues', 'Stadiums &amp; venues', 'Event counting'), R('platform', 'Platform', 'Sensors for outdoor spaces')])
